INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Braucht Servervirtualisierung immer einen Hypervisor?', 2, '[{"text": "Ja", "correct": true, "because": "Grundlage für VMs"}, {"text": "Nein", "correct": false, "because": "Selten ohne Hypervisor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Hypervisor wähle ich für kostenlose Nutzung?', 3, '[{"text": "VMware ESXi", "correct": true, "because": "Kostenlose Basisversion verfügbar"}, {"text": "Hyper-V", "correct": false, "because": "Lizenzkosten bei Windows"}, {"text": "Proprietäre Lösung", "correct": false, "because": "Oft kostenpflichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Konsolidierung bei Virtualisierung nützlich?', 5, '[{"text": "Ressourcennutzung", "correct": true, "because": "Effizientere Hardwareauslastung"}, {"text": "Kostensenkung", "correct": true, "because": "Weniger physische Server"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht gewünscht"}, {"text": "Komplexe Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Hypervisor Typ 1 läuft direkt auf Hardware. b) Konsolidierung erhöht die Hardwarekosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kosten sinken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Hypervisors für ein kleines Unternehmen?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zu Hardware passen"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "High-End-Gaming", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Typ-2-Hypervisors auf einem BS laufen?', 2, '[{"text": "Ja", "correct": true, "because": "Benötigen Host-BS"}, {"text": "Nein", "correct": false, "because": "Typ 1 läuft direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für Konsolidierung?', 3, '[{"text": "Ressourcenoptimierung", "correct": true, "because": "Maximale Auslastung"}, {"text": "Einfache GUI", "correct": false, "because": "Sekundär"}, {"text": "Minimale VMs", "correct": false, "because": "Gegenteil von Konsolidierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Servervirtualisierung?', 5, '[{"text": "Konsolidierung", "correct": true, "because": "Weniger physische Server"}, {"text": "Flexibilität", "correct": true, "because": "Schnelle VM-Bereitstellung"}, {"text": "Geringere Sicherheit", "correct": false, "because": "Nicht zwingend"}, {"text": "Höhere Latenz", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Hypervisors erhöhen die Effizienz. b) Konsolidierung ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch für kleine nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Servervirtualisierung?', 4, '[{"text": "Leistungsstarke Hardware", "correct": false, "because": "Basis für VMs"}, {"text": "Hypervisor", "correct": false, "because": "Kern der Virtualisierung"}, {"text": "Lokale Festplatten", "correct": true, "because": "SAN oder NAS oft genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Typ-1-Hypervisor schneller als Typ 2?', 2, '[{"text": "Ja", "correct": true, "because": "Direkt auf Hardware, kein BS-Overhead"}, {"text": "Nein", "correct": false, "because": "Typ 2 hat mehr Schichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für einen Hypervisor entscheidend?', 4, '[{"text": "Hardwareunterstützung", "correct": true, "because": "Muss kompatibel sein"}, {"text": "VM-Management", "correct": true, "because": "Effiziente Verwaltung"}, {"text": "Geringer RAM", "correct": false, "because": "Mehr Ressourcen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Virtualisierung die Sicherheit senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit hängt von Konfiguration ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für Konsolidierung in einem Rechenzentrum?', 3, '[{"text": "Hohe Dichte", "correct": true, "because": "Maximale VMs pro Server"}, {"text": "Einfache Bedienung", "correct": false, "because": "Sekundär"}, {"text": "Geringe Kosten", "correct": false, "because": "Effizienz zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Konsolidierung spart Platz. b) Hypervisors brauchen keine Updates.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Updates nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Servervirtualisierung?', 5, '[{"text": "Komplexität", "correct": true, "because": "Verwaltung aufwendiger"}, {"text": "Single Point of Failure", "correct": true, "because": "Hypervisor-Ausfall kritisch"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht zwingend"}, {"text": "Einfachere Hardware", "correct": false, "because": "Mehr Leistung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Virtualisierung für einen Webserver unwichtig?', 3, '[{"text": "Netzwerkleistung", "correct": false, "because": "Wichtig für Anfragen"}, {"text": "VM-Ressourcen", "correct": false, "because": "Bestimmt Performance"}, {"text": "Lokale GPU", "correct": true, "because": "Webserver braucht keine Grafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Konsolidierung die Hardwareauslastung?', 3, '[{"text": "Ja", "correct": true, "because": "Mehr VMs pro Server"}, {"text": "Nein", "correct": false, "because": "Effizienz ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Virtualisierung ohne Hypervisor möglich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Hypervisor ist essenziell"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Hypervisor wähle ich für ein großes Unternehmen?', 4, '[{"text": "vSphere", "correct": true, "because": "Skalierbar und robust"}, {"text": "VirtualBox", "correct": false, "because": "Eher für Tests"}, {"text": "Keinen", "correct": false, "because": "Hypervisor nötig"}]');
